package com.vaultora.vault;
import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/vault") public class VaultController {private final VaultService vaults;public VaultController(VaultService v){vaults=v;}@GetMapping public ResponseEntity<VaultDtos.EncryptedVaultResponse> get(Authentication a){var v=vaults.get(a.getName());return v==null?ResponseEntity.noContent().build():ResponseEntity.ok(v);}@PutMapping public VaultDtos.EncryptedVaultResponse save(@Valid @RequestBody VaultDtos.EncryptedVaultRequest r,@RequestHeader(value="If-Match",required=false,defaultValue="0") long revision,Authentication a){return vaults.save(a.getName(),r,revision);}}
